public class SolutionTest {
    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private interface ThrowingAction { void run() throws Exception; }

    private static Throwable expect(Class<? extends Throwable> type, ThrowingAction action) {
        try {
            action.run();
            throw new AssertionError("Expected " + type.getName());
        } catch (Throwable t) {
            if (!type.isInstance(t)) throw new AssertionError("Expected " + type.getName() + " but got " + t, t);
            return t;
        }
    }

    public static void main(String[] args) throws Exception {
        Solution.ResourceKey a = new Solution.ResourceKey("  report-1  ");
        Solution.ResourceKey a2 = new Solution.ResourceKey("report-1");
        Solution.ResourceKey b = new Solution.ResourceKey("report-2");
        check(a.equals(a2) && a2.equals(a), "ResourceKey equality must use normalized value");
        check(a.hashCode() == a2.hashCode(), "equal keys need equal hashes");
        check(!a.equals(b), "different keys must differ");

        Solution.CapabilityTable first = Solution.newTable();
        Solution.CapabilityTable second = Solution.newTable();
        Solution.grant(first, a, "  alice  ", Solution.Capability.VIEW);
        Solution.grant(first, a2, "alice", Solution.Capability.VIEW);
        Solution.grant(first, a, "alice", Solution.Capability.MODIFY);
        check(Solution.contains(first, a2, " alice ", Solution.Capability.VIEW), "normalized grant missing");
        check(Solution.contains(first, a, "alice", Solution.Capability.MODIFY), "second capability missing");
        check(!Solution.contains(second, a, "alice", Solution.Capability.VIEW), "tables share state");
        Solution.require(first, a, "alice", Solution.Capability.VIEW);

        Solution.revoke(first, a, "alice", Solution.Capability.VIEW);
        check(!Solution.contains(first, a, "alice", Solution.Capability.VIEW), "revoke failed");
        check(Solution.contains(first, a, "alice", Solution.Capability.MODIFY), "revoke removed another capability");
        Solution.revoke(first, a, "alice", Solution.Capability.VIEW);
        Solution.revoke(first, b, "nobody", Solution.Capability.RUN);

        Throwable missing = expect(Solution.MissingCapabilityException.class,
                () -> Solution.require(first, a, "  alice  ", Solution.Capability.RUN));
        String message = missing.getMessage();
        check(message != null && message.contains("alice") && message.contains("report-1")
                && message.contains("RUN"), "missing-capability message lacks normalized details: " + message);

        expect(IllegalArgumentException.class, () -> new Solution.ResourceKey(null));
        expect(IllegalArgumentException.class, () -> new Solution.ResourceKey(" \t "));
        expect(IllegalArgumentException.class, () -> Solution.grant(null, a, "x", Solution.Capability.VIEW));
        expect(IllegalArgumentException.class, () -> Solution.grant(first, null, "x", Solution.Capability.VIEW));
        expect(IllegalArgumentException.class, () -> Solution.grant(first, a, null, Solution.Capability.VIEW));
        expect(IllegalArgumentException.class, () -> Solution.grant(first, a, "  ", Solution.Capability.VIEW));
        expect(IllegalArgumentException.class, () -> Solution.grant(first, a, "x", null));
        expect(IllegalArgumentException.class, () -> Solution.contains(first, a, "", Solution.Capability.VIEW));
        expect(IllegalArgumentException.class, () -> Solution.revoke(first, a, "x", null));
        expect(IllegalArgumentException.class, () -> Solution.require(first, null, "x", Solution.Capability.VIEW));
    }
}

